class Solution {
public:
    int longestAlternatingSubarray(vector<int>& nums, int threshold) {
        int n = nums.size();
        int ans = 0;
        for (int l = 0; l < n; ++l) {
            if (nums[l] % 2 == 0 && nums[l] <= threshold) {
                int r = l;
                while (r + 1 < n && nums[r + 1] <= threshold && nums[r + 1] % 2 != nums[r] % 2) {
                    r++;
                }
                ans = max(ans, r - l + 1);
            }
        }
        return ans;
    }
};

class Solution {
    public int longestAlternatingSubarray(int[] nums, int threshold) {
        int n = nums.length;
        int ans = 0;
        for (int l = 0; l < n; l++) {
            if (nums[l] % 2 == 0 && nums[l] <= threshold) {
                int r = l;
                while (r + 1 < n && nums[r + 1] <= threshold && nums[r + 1] % 2 != nums[r] % 2) {
                    r++;
                }
                ans = Math.max(ans, r - l + 1);
            }
        }
        return ans;
    }
}

var longestAlternatingSubarray = function(nums, threshold) {
    const n = nums.length;
    let ans = 0;
    for (let l = 0; l < n; l++) {
        if (nums[l] % 2 === 0 && nums[l] <= threshold) {
            let r = l;
            while (r + 1 < n && nums[r + 1] <= threshold && nums[r + 1] % 2 !== nums[r] % 2) {
                r++;
            }
            ans = Math.max(ans, r - l + 1);
        }
